/*
A = T ⊗ P
                    where 
                    T: ℝ ^ (2×3): a sequence
                    P: ℝ ^ (2×3): a sequence
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    MatrixD A;

    heartlib(
        const Eigen::Matrix<double, 2, 3> & T,
        const Eigen::Matrix<double, 2, 3> & P)
    {

        // A = T ⊗ P
        MatrixD kron(4, 9);
        for( int i=0; i<2; i++){
            for( int j=0; j<3; j++){
                kron.block(i*2,j*3,2,3) = (T)(i, j)*(P);
            }
        }
        A = kron;
    }
};

