function output = heartlib(T, P)
% output = heartlib(T, P)
%
%    A = T ⊗ P
%                        where 
%                        T: ℝ ^ (2×3): a sequence
%                        P: ℝ ^ (2×3): a sequence
    assert( isequal(size(T), [2, 3]) );
    assert( isequal(size(P), [2, 3]) );

    % A = T ⊗ P

    A = kron(T, P);
    output.A = A;
end

